// Ejemplo conceptual en C: Espera ocupada (Spinlock) vs Bloqueo
#include <stdio.h>
#include <pthread.h>
#include <stdatomic.h>
#include <unistd.h>

atomic_flag spinlock = ATOMIC_FLAG_INIT;

void* con_espera_ocupada(void* arg) {
    // Espera activa (consume CPU en un bucle continuo):
    while (atomic_flag_test_and_set(&spinlock)) {
        // Spin...
    }
    // Sección crítica
    printf("En sección crítica con spinlock\n");
    atomic_flag_clear(&spinlock);
    return NULL;
}

// Bloqueo (el hilo cede CPU al SO vía llamadas al sistema):
// sem_wait(&sem); // Se duerme y libera la CPU
// ...
// sem_post(&sem); // Despierta al bloqueado

// Demostración de condición de carrera si wait y signal NO fuesen atómicas:
#include <stdio.h>

int S = 1;

// Si esta función se interrumpiera entre la verificación y el decremento:
void wait_no_atomico(int *sem) {
    while (*sem <= 0); // Paso 1: evaluar condición
    // ---> INTERRUPCIÓN AQUÍ: El planificador conmuta a otro hilo
    (*sem)--;          // Paso 2: decrementar
}

// En hardware real, las arquitecturas ofrecen instrucciones indivisibles:
// - Test-and-Set (TAS)
// - Compare-and-Swap (CAS)
// - Load-Linked / Store-Conditional (LL/SC)

// Implementación conceptual de semáforos en Monoprocesador (Kernel):
typedef struct {
    int valor;
    struct cola_procesos *cola;
} semaforo_t;

void wait_kernel(semaforo_t *s) {
    disable_interrupts(); // Desactiva interrupciones en el CPU local
    s->valor--;
    if (s->valor < 0) {
        agregar_a_cola(s->cola, proceso_actual);
        bloquear_proceso(); // Cede CPU y reactiva interrupciones en context switch
    }
    enable_interrupts();
}

void signal_kernel(semaforo_t *s) {
    disable_interrupts();
    s->valor++;
    if (s->valor <= 0) {
        proceso_t *p = remover_de_cola(s->cola);
        despertar_proceso(p);
    }
    enable_interrupts();
}

/**
 * ============================================================================
 * SISTEMAS OPERATIVOS - UNS (Trabajo Práctico N° 4: Sincronización)
 * Concepto 4: Barreras de Sincronización (pthread_barrier_t)
 * ============================================================================
 * Consigna:
 * Demostración práctica de una barrera de sincronización en C con POSIX threads.
 * Ningún hilo puede avanzar a la fase siguiente hasta que todos los hilos
 * hayan completado la fase actual y alcanzado la barrera.
 *
 * Compilación:
 *   gcc -pthread ejemplo_barreras_pthread.c -o ejemplo_barreras
 * Ejecución:
 *   ./ejemplo_barreras
 * ============================================================================
 */

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

#define NUM_HILOS 4

pthread_barrier_t barrera;

void* trabajador(void* arg) {
    int id = *((int*)arg);

    // --- FASE 1 ---
    int tiempo_fase1 = (rand() % 300 + 100) * 1000;
    printf("[Hilo %d] Ejecutando Fase 1 (tarda %d ms)...\n", id, tiempo_fase1 / 1000);
    usleep(tiempo_fase1);
    printf("[Hilo %d] -> Llegó a la BARRERA. Esperando a los demás...\n", id);

    // Esperar a que los 4 hilos alcancen este punto
    pthread_barrier_wait(&barrera);

    // --- FASE 2 ---
    printf(">>> [Hilo %d] ⭐ ¡Barrera superada! Iniciando Fase 2 sincronizada.\n", id);
    usleep(150000);

    return NULL;
}

int main(int argc, char* argv[]) {
    pthread_t hilos[NUM_HILOS];
    int ids[NUM_HILOS];

    srand(time(NULL));

    printf("====================================================\n");
    printf("   TP4 - Concepto 4: Barreras de Sincronización     \n");
    printf("   (Grupo de %d hilos sincronizados)                \n", NUM_HILOS);
    printf("====================================================\n\n");

    // Inicializar barrera para NUM_HILOS
    pthread_barrier_init(&barrera, NULL, NUM_HILOS);

    for (int i = 0; i < NUM_HILOS; i++) {
        ids[i] = i + 1;
        pthread_create(&hilos[i], NULL, trabajador, &ids[i]);
    }

    for (int i = 0; i < NUM_HILOS; i++) {
        pthread_join(hilos[i], NULL);
    }

    pthread_barrier_destroy(&barrera);

    printf("\nTodos los hilos completaron ambas fases sincronizados.\n");
    return EXIT_SUCCESS;
}

// Comportamiento de Hilos a Nivel de Kernel vs Usuario:
// En KLT (POSIX pthread estándar en Linux NPTL):
// Cada hilo es una entidad de planificación en el kernel (task_struct).
// Si Hilo 1 se bloquea en sem_wait, Hilo 2 continúa ejecutando en otro core.

// En ULT puro (bibliotecas históricas como GNU Pth o corutinas):
// Si Hilo 1 hace una llamada al sistema bloqueante al kernel:
// sys_sem_wait(kernel_sem_id);
// -> El kernel bloquea TODO el proceso. Hilo 2 queda congelado.

// Comparación directa en C: Mutex (con ownership) vs Semáforo Binario
#include <pthread.h>
#include <semaphore.h>

pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;
sem_t sem_bin;

void demo_mutex() {
    pthread_mutex_lock(&mtx);
    // Sección crítica: SOLO este hilo puede desbloquear
    pthread_mutex_unlock(&mtx);
}

void demo_semaforo_senal() {
    sem_init(&sem_bin, 0, 0);
    // Hilo 1 puede esperar una señal:
    // sem_wait(&sem_bin);
    // Y un Hilo 2 DIFERENTE (o una interrupción) emite la señal:
    // sem_post(&sem_bin);
}

// Rutinas de sistema operativo asociadas a los nuevos semáforos de canal y memoria:
// 1. Solicitud de E/S en canal de cinta:
void sys_iniciar_io_cinta() {
    sem_wait(&sem_canal_cinta); // Transición: Ejecutando -> Bloqueado en Cinta
    iniciar_transferencia_hardware();
}

// 2. Manejador de interrupción fin de E/S:
void isr_fin_io_cinta() {
    sem_post(&sem_canal_cinta); // Transición: Bloqueado en Cinta -> Listo
}

// 3. Manejo de memoria dinámica:
void* sys_malloc(size_t bytes) {
    if (!hay_marcos_libres(bytes)) {
        sem_wait(&sem_memoria); // Transición: Ejecutando -> Bloqueado Memoria (posible Swap)
    }
    return asignar_marcos(bytes);
}

/**
 * ============================================================================
 * SISTEMAS OPERATIVOS - UNS (Trabajo Práctico N° 4: Sincronización)
 * Ejercicio 1 (Problema 1): Tweedledum y Tweedledee
 * ============================================================================
 * Consigna:
 * Tweedledum y Tweedledee intercambian opiniones a través de la variable
 * compartida X en estricta alternancia. Las primitivas primitivas Sleep y Wakeup
 * fallaban por "Lost Wakeup". Se implementa la solución correcta utilizando
 * semáforos POSIX para garantizar alternancia estricta sin pérdida de señales.
 *
 * Compilación:
 *   gcc -pthread ejercicio01_tweedledum_tweedledee.c -o ejercicio01
 * Ejecución:
 *   ./ejercicio01
 * ============================================================================
 */

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define MAX_RONDAS 6

// Semáforos para forzar alternancia estricta
sem_t sem_dum;
sem_t sem_dee;

// Variable global compartida
int x = 0;

// Función que simula la discusión e intercambio de opiniones
int Quarrel(int val, const char* nombre, int ronda) {
    int nuevo_val = val + 1;
    printf("[%s | Ronda %d] Opina sobre X: valor anterior = %d, nuevo valor = %d\n",
           nombre, ronda, val, nuevo_val);
    usleep(250000); // Pausa de 250ms para visualizar la alternancia
    return nuevo_val;
}

// Hilo Tweedledum
void* tweedledum_func(void* arg) {
    for (int i = 1; i <= MAX_RONDAS; i++) {
        // Espera su turno
        sem_wait(&sem_dum);

        // Sección Crítica: modificar variable compartida
        x = Quarrel(x, "Tweedledum", i);

        // Despierta a Tweedledee
        sem_post(&sem_dee);
    }
    return NULL;
}

// Hilo Tweedledee
void* tweedledee_func(void* arg) {
    for (int i = 1; i <= MAX_RONDAS; i++) {
        // Espera su turno
        sem_wait(&sem_dee);

        // Sección Crítica: modificar variable compartida
        x = Quarrel(x, "Tweedledee", i);

        // Despierta a Tweedledum
        sem_post(&sem_dum);
    }
    return NULL;
}

int main(int argc, char* argv[]) {
    pthread_t th_dum, th_dee;

    printf("====================================================\n");
    printf("   TP4 - Ejercicio 1: Tweedledum y Tweedledee       \n");
    printf("====================================================\n");

    // Inicialización de semáforos:
    // sem_dum inicia en 0 (espera)
    // sem_dee inicia en 1 (Tweedledee comienza primero)
    if (sem_init(&sem_dum, 0, 0) != 0 || sem_init(&sem_dee, 0, 1) != 0) {
        perror("Error al inicializar los semáforos");
        exit(EXIT_FAILURE);
    }

    printf("Iniciando hilos con alternancia estricta...\n\n");

    // Creación de los hilos
    if (pthread_create(&th_dum, NULL, tweedledum_func, NULL) != 0) {
        perror("Error al crear hilo Tweedledum");
        exit(EXIT_FAILURE);
    }
    if (pthread_create(&th_dee, NULL, tweedledee_func, NULL) != 0) {
        perror("Error al crear hilo Tweedledee");
        exit(EXIT_FAILURE);
    }

    // Esperar a que ambos hilos finalicen sus rondas
    pthread_join(th_dum, NULL);
    pthread_join(th_dee, NULL);

    // Destrucción de semáforos
    sem_destroy(&sem_dum);
    sem_destroy(&sem_dee);

    printf("\nEjecución finalizada con éxito. Valor final de X = %d (esperado %d).\n",
           x, MAX_RONDAS * 2);
    return EXIT_SUCCESS;
}

/**
 * ============================================================================
 * SISTEMAS OPERATIVOS - UNS (Trabajo Práctico N° 4: Sincronización)
 * Ejercicio 2 (Problema 2): Productor - Consumidor (Buffer Acotado)
 * ============================================================================
 * Consigna:
 * El código de la consigna contenía un Deadlock: el productor hacía down(&mutex)
 * ANTES de down(&vacio). Si el buffer se llenaba, el productor se bloqueaba en
 * 'vacio' reteniendo el 'mutex', impidiendo que el consumidor pudiera consumir.
 *
 * Corrección implementada:
 * Se invierte el orden en el Productor:
 *   1° sem_wait(&vacio)  -> Esperar que haya espacio libre
 *   2° sem_wait(&mutex)  -> Obtener acceso exclusivo al buffer
 *
 * Compilación:
 *   gcc -pthread ejercicio02_productor_consumidor.c -o ejercicio02
 * Ejecución:
 *   ./ejercicio02
 * ============================================================================
 */

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define N 5               // Capacidad del buffer circular
#define TOTAL_ITEMS 15    // Total de elementos a producir y consumir

// Buffer compartido
int buffer[N];
int in = 0;   // Índice de inserción
int out = 0;  // Índice de extracción

// Semáforos de sincronización
sem_t mutex;  // Exclusión mutua para modificar el buffer
sem_t vacio;  // Cuenta lugares libres disponibles (inicia en N)
sem_t lleno;  // Cuenta elementos disponibles para consumir (inicia en 0)

// Hilo Productor
void* productor(void* arg) {
    int id = *((int*)arg);
    for (int i = 1; i <= TOTAL_ITEMS; i++) {
        int dato = i * 10; // Dato producido

        // 1. Esperar que haya al menos un espacio libre
        sem_wait(&vacio);

        // 2. Entrar a la sección crítica (exclusión mutua)
        sem_wait(&mutex);

        // --- SECCIÓN CRÍTICA ---
        buffer[in] = dato;
        printf("[Productor %d] Insertó dato: %3d en posición [%d]\n", id, dato, in);
        in = (in + 1) % N;
        // -----------------------

        // 3. Salir de la sección crítica
        sem_post(&mutex);

        // 4. Notificar que hay un nuevo elemento disponible
        sem_post(&lleno);

        usleep(150000); // Simula tiempo de producción (150ms)
    }
    return NULL;
}

// Hilo Consumidor
void* consumidor(void* arg) {
    int id = *((int*)arg);
    for (int i = 1; i <= TOTAL_ITEMS; i++) {
        // 1. Esperar que haya al menos un elemento disponible
        sem_wait(&lleno);

        // 2. Entrar a la sección crítica (exclusión mutua)
        sem_wait(&mutex);

        // --- SECCIÓN CRÍTICA ---
        int dato = buffer[out];
        printf("    [Consumidor %d] Extrajo dato: %3d de posición [%d]\n", id, dato, out);
        out = (out + 1) % N;
        // -----------------------

        // 3. Salir de la sección crítica
        sem_post(&mutex);

        // 4. Notificar que se liberó un espacio en el buffer
        sem_post(&vacio);

        usleep(250000); // Simula tiempo de consumo (250ms)
    }
    return NULL;
}

int main(int argc, char* argv[]) {
    pthread_t th_prod, th_cons;
    int id_prod = 1, id_cons = 1;

    printf("====================================================\n");
    printf("   TP4 - Ejercicio 2: Productor - Consumidor       \n");
    printf("   (Buffer Circular Acotado de %d elementos)        \n", N);
    printf("====================================================\n");

    // Inicialización de semáforos
    sem_init(&mutex, 0, 1); // Mutex binario (inicia en 1)
    sem_init(&vacio, 0, N); // N espacios vacíos al inicio
    sem_init(&lleno, 0, 0); // 0 elementos llenos al inicio

    // Creación de hilos
    pthread_create(&th_prod, NULL, productor, &id_prod);
    pthread_create(&th_cons, NULL, consumidor, &id_cons);

    // Esperar finalización
    pthread_join(th_prod, NULL);
    pthread_join(th_cons, NULL);

    // Destrucción de semáforos
    sem_destroy(&mutex);
    sem_destroy(&vacio);
    sem_destroy(&lleno);

    printf("\nTodos los elementos (%d) fueron producidos y consumidos sin deadlock.\n", TOTAL_ITEMS);
    return EXIT_SUCCESS;
}

/**
 * ============================================================================
 * SISTEMAS OPERATIVOS - UNS (Trabajo Práctico N° 4: Sincronización)
 * Ejercicio 3 (Problema 3): La Cena de los Filósofos (Tanenbaum/Dijkstra)
 * ============================================================================
 * Errores corregidos respecto a la consigna original:
 * 1. Macro de índice negativo:
 *    Original: #define Izquierdo (i - 1) % N  -> En C (0-1)%6 = -1 (error de puntero)
 *    Corregido: #define Izquierdo (i + N - 1) % N
 * 2. Condición de carrera en dejar_tenedores:
 *    Original: up(&mutex) ANTES de test(Izquierdo) y test(Derecho).
 *    Corregido: up(&mutex) AL FINAL, protegiendo las verificaciones de los vecinos.
 * 3. Inicialización de semáforos s[N] en 0 para cada filósofo.
 *
 * Compilación:
 *   gcc -pthread ejercicio03_filosofos.c -o ejercicio03
 * Ejecución:
 *   ./ejercicio03
 * ============================================================================
 */

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define N 5                  // Número de filósofos en la mesa circular
#define RONDAS_POR_FILOSOFO 3 // Cada filósofo piensa y come 3 veces para la prueba

// Macros seguras para vecinos circulares (sin índices negativos)
#define IZQUIERDO (i + N - 1) % N
#define DERECHO   (i + 1) % N

// Estados posibles de cada filósofo
#define PENSANDO     0
#define TIENE_HAMBRE 1
#define COMIENDO     2

int estado[N];
sem_t mutex;  // Exclusión mutua para inspeccionar y cambiar estados
sem_t s[N];   // Un semáforo privado por filósofo (inician en 0)

// Comprueba si el filósofo i tiene hambre y sus dos vecinos NO están comiendo
void test(int i) {
    if (estado[i] == TIENE_HAMBRE &&
        estado[IZQUIERDO] != COMIENDO &&
        estado[DERECHO] != COMIENDO) {

        estado[i] = COMIENDO;
        printf("  [Filósofo %d] -> Tomó ambos tenedores y empieza a COMER.\n", i);
        // Habilita al filósofo para comer (desbloquea su sem_wait si estaba esperando)
        sem_post(&s[i]);
    }
}

// Intenta tomar ambos tenedores
void tomar_tenedores(int i) {
    sem_wait(&mutex);

    estado[i] = TIENE_HAMBRE;
    printf("[Filósofo %d] TIENE HAMBRE e intenta tomar tenedores.\n", i);
    test(i); // Si los dos tenedores están libres, pasará a COMIENDO y hará post en s[i]

    sem_post(&mutex);

    // Si no pudo comer, se bloquea aquí esperando que sus vecinos lo habiliten
    sem_wait(&s[i]);
}

// Deja ambos tenedores y comprueba si los vecinos pueden comer ahora
void dejar_tenedores(int i) {
    sem_wait(&mutex);

    estado[i] = PENSANDO;
    printf("[Filósofo %d] Terminó de comer, suelta tenedores y vuelve a PENSAR.\n", i);

    // CORRECCIÓN CRÍTICA: Se evalúan los vecinos DENTRO del mutex
    test(IZQUIERDO);
    test(DERECHO);

    sem_post(&mutex);
}

void pensar(int i) {
    usleep((rand() % 300 + 100) * 1000); // 100ms a 400ms
}

void comer(int i) {
    usleep((rand() % 300 + 100) * 1000); // 100ms a 400ms
}

// Rutina de cada filósofo
void* filosofo(void* arg) {
    int id = *((int*)arg);

    for (int r = 1; r <= RONDAS_POR_FILOSOFO; r++) {
        pensar(id);
        tomar_tenedores(id);
        comer(id);
        dejar_tenedores(id);
    }

    printf(">>> Filósofo %d completó todas sus rondas.\n", id);
    return NULL;
}

int main(int argc, char* argv[]) {
    pthread_t hilos[N];
    int ids[N];

    srand(time(NULL));

    printf("====================================================\n");
    printf("   TP4 - Ejercicio 3: Cena de los Filósofos (%d)    \n", N);
    printf("====================================================\n");

    // Inicialización del mutex y los semáforos privados
    sem_init(&mutex, 0, 1);
    for (int i = 0; i < N; i++) {
        estado[i] = PENSANDO;
        sem_init(&s[i], 0, 0); // Todos inician en 0
        ids[i] = i;
    }

    // Creación de los hilos de los filósofos
    for (int i = 0; i < N; i++) {
        pthread_create(&hilos[i], NULL, filosofo, &ids[i]);
    }

    // Esperar finalización de todos los filósofos
    for (int i = 0; i < N; i++) {
        pthread_join(hilos[i], NULL);
    }

    // Limpieza
    sem_destroy(&mutex);
    for (int i = 0; i < N; i++) {
        sem_destroy(&s[i]);
    }

    printf("\nSimulación finalizada sin interbloqueos ni condiciones de carrera.\n");
    return EXIT_SUCCESS;
}

steps.explanation:
**Análisis y corrección de los 3 errores de la consigna:**

1. **Error aritmético de Macro en C (Índice Negativo):**
   La macro `#define Izquierdo (i-1)%N` produce un valor negativo en lenguaje C cuando `i = 0` (`(0-1)%6 = -1`). Al evaluar `estado[Izquierdo]`, accede a memoria fuera de los límites del arreglo (`estado[-1]`).
   *Corrección:* `#define Izquierdo (i + N - 1) % N`

2. **Condición de Carrera en `dejar_tenedores`:**
   En el código de la consigna original:
   ```c
   void dejar_tenedores(int i) {
       down(&mutex);
       estado[i] = Pensando;
       up(&mutex); // <-- ¡Libera el mutex prematuramente!
       test(Izquierdo);
       test(Derecho);
   }
   ```
   Las funciones `test(Izquierdo)` y `test(Derecho)` leen y modifican `estado[i]` de los vecinos sin estar protegidas por `mutex`. Si dos vecinos terminan a la vez, se produce una condición de carrera.
   *Corrección:* Mover `up(&mutex)` al final de la función para proteger el testeo de los vecinos.

3. **Inicialización de semáforos:**
   Los semáforos del arreglo `s[N]` deben inicializarse explícitamente en `0` para que el filósofo que no pueda comer se bloquee en `sem_wait(&s[i])`.

