/**
 * ============================================================================
 * SISTEMAS OPERATIVOS - UNS (Trabajo Práctico N° 4: Sincronización)
 * Ejercicio 5 (Problema 5): Fábrica de Bicicletas (MountanenBike)
 * ============================================================================
 * Componentes y operarios:
 * - OP1: Monta ruedas (produce de a 1, la bici requiere 2 ruedas).
 * - OP2: Monta cuadros (la bici requiere 1 cuadro).
 * - OP3: Monta manillares (la bici requiere 1 manillar).
 * - Montador: Espera 2 ruedas, 1 cuadro y 1 manillar, y ensambla la bicicleta.
 *
 * Inciso b contemplado: OP1 tiene capacidad de fabricar hasta 2 ruedas
 * (puedo_rueda inicializado en 2).
 *
 * Compilación:
 *   gcc -pthread ejercicio05_fabrica_bicicletas.c -o ejercicio05
 * Ejecución:
 *   ./ejercicio05
 * ============================================================================
 */

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define TOTAL_BICICLETAS 5

// Semáforos de permiso para fabricar (capacidad disponible)
sem_t puedo_rueda;    // Inicializado en 2 (puede adelantar hasta 2 ruedas)
sem_t puedo_cuadro;   // Inicializado en 1
sem_t puedo_manillar; // Inicializado en 1

// Semáforos que indican piezas listas para el montador
sem_t hay_rueda;      // Inicializado en 0 (acumula hasta 2 para el montador)
sem_t hay_cuadro;     // Inicializado en 0
sem_t hay_manillar;   // Inicializado en 0

// OP1: Fabrica ruedas (debe fabricar 2 ruedas por cada bicicleta)
void* operario1_ruedas(void* arg) {
    int total_ruedas = TOTAL_BICICLETAS * 2;
    for (int r = 1; r <= total_ruedas; r++) {
        sem_wait(&puedo_rueda);
        printf("[OP1 - Ruedas]    Fabricando rueda #%d...\n", r);
        usleep(100000); // 100ms
        printf("[OP1 - Ruedas]    ✓ Rueda #%d LISTA.\n", r);
        sem_post(&hay_rueda);
    }
    return NULL;
}

// OP2: Fabrica cuadros (1 por bicicleta)
void* operario2_cuadro(void* arg) {
    for (int c = 1; c <= TOTAL_BICICLETAS; c++) {
        sem_wait(&puedo_cuadro);
        printf("[OP2 - Cuadros]   Fabricando cuadro #%d...\n", c);
        usleep(180000); // 180ms
        printf("[OP2 - Cuadros]   ✓ Cuadro #%d LISTO.\n", c);
        sem_post(&hay_cuadro);
    }
    return NULL;
}

// OP3: Fabrica manillares (1 por bicicleta)
void* operario3_manillar(void* arg) {
    for (int m = 1; m <= TOTAL_BICICLETAS; m++) {
        sem_wait(&puedo_manillar);
        printf("[OP3 - Manillar]  Fabricando manillar #%d...\n", m);
        usleep(120000); // 120ms
        printf("[OP3 - Manillar]  ✓ Manillar #%d LISTO.\n", m);
        sem_post(&hay_manillar);
    }
    return NULL;
}

// Montador: Ensambla la bicicleta con 2 ruedas, 1 cuadro y 1 manillar
void* montador(void* arg) {
    for (int b = 1; b <= TOTAL_BICICLETAS; b++) {
        printf("\n>>> [Montador] Esperando piezas para Bicicleta #%d...\n", b);

        // Toma 2 ruedas
        sem_wait(&hay_rueda);
        sem_wait(&hay_rueda);

        // Toma 1 cuadro
        sem_wait(&hay_cuadro);

        // Toma 1 manillar
        sem_wait(&hay_manillar);

        printf(">>> [Montador] ¡Piezas recolectadas! Ensamblando Bicicleta #%d 🚲...\n", b);
        usleep(250000); // 250ms de ensamble
        printf(">>> [Montador] ⭐ ¡BICICLETA #%d TERMINADA CON ÉXITO!\n\n", b);

        // Habilita a los operarios a fabricar nuevas piezas
        sem_post(&puedo_rueda);
        sem_post(&puedo_rueda);
        sem_post(&puedo_cuadro);
        sem_post(&puedo_manillar);
    }
    return NULL;
}

int main(int argc, char* argv[]) {
    pthread_t th_op1, th_op2, th_op3, th_montador;

    printf("====================================================\n");
    printf("   TP4 - Ejercicio 5: Fábrica MountanenBike         \n");
    printf("   Meta: Fabricar %d bicicletas completas           \n", TOTAL_BICICLETAS);
    printf("====================================================\n\n");

    // Inicialización de semáforos:
    // puedo_rueda = 2 (permite a OP1 adelantar las dos ruedas)
    // puedo_cuadro = 1, puedo_manillar = 1
    sem_init(&puedo_rueda, 0, 2);
    sem_init(&puedo_cuadro, 0, 1);
    sem_init(&puedo_manillar, 0, 1);

    // Piezas listas inicialmente = 0
    sem_init(&hay_rueda, 0, 0);
    sem_init(&hay_cuadro, 0, 0);
    sem_init(&hay_manillar, 0, 0);

    // Creación de hilos
    pthread_create(&th_op1, NULL, operario1_ruedas, NULL);
    pthread_create(&th_op2, NULL, operario2_cuadro, NULL);
    pthread_create(&th_op3, NULL, operario3_manillar, NULL);
    pthread_create(&th_montador, NULL, montador, NULL);

    // Esperar finalización
    pthread_join(th_op1, NULL);
    pthread_join(th_op2, NULL);
    pthread_join(th_op3, NULL);
    pthread_join(th_montador, NULL);

    // Destrucción de semáforos
    sem_destroy(&puedo_rueda);
    sem_destroy(&puedo_cuadro);
    sem_destroy(&puedo_manillar);
    sem_destroy(&hay_rueda);
    sem_destroy(&hay_cuadro);
    sem_destroy(&hay_manillar);

    printf("Lote de %d bicicletas fabricado exitosamente.\n", TOTAL_BICICLETAS);
    return EXIT_SUCCESS;
}

/**
 * ============================================================================
 * SISTEMAS OPERATIVOS - UNS (Trabajo Práctico N° 4: Sincronización)
 * Ejercicio 6 (Problema 6): Fumadores de Cigarrillos (Patil 1971)
 * ============================================================================
 * Consigna:
 * Tres fumadores y un agente.
 * - Fumador 1: Posee Tabaco    -> Necesita Papel y Fósforos
 * - Fumador 2: Posee Papel     -> Necesita Tabaco y Fósforos
 * - Fumador 3: Posee Fósforos  -> Necesita Tabaco y Papel
 *
 * El agente coloca dos ingredientes al azar en la mesa. El fumador que tiene
 * el ingrediente restante arma el cigarrillo, fuma y le avisa al agente
 * cuando termina para iniciar una nueva ronda.
 *
 * Compilación:
 *   gcc -pthread ejercicio06_fumadores.c -o ejercicio06
 * Ejecución:
 *   ./ejercicio06
 * ============================================================================
 */

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <time.h>

#define TOTAL_RONDAS 6

// Semáforo para el agente (indica que la mesa está libre)
sem_t sem_agente;

// Semáforos que despiertan al fumador correspondiente según lo que falta
sem_t sem_fumador_tabaco;   // Mesa tiene: Papel + Fósforos
sem_t sem_fumador_papel;    // Mesa tiene: Tabaco + Fósforos
sem_t sem_fumador_fosforo;  // Mesa tiene: Tabaco + Papel

// Hilo del Agente
void* agente(void* arg) {
    for (int r = 1; r <= TOTAL_RONDAS; r++) {
        // Espera a que la mesa quede libre (el fumador anterior terminó)
        sem_wait(&sem_agente);

        int ingrediente_que_falta = rand() % 3;

        printf("\n================ [Ronda %d de %d] ================\n", r, TOTAL_RONDAS);
        if (ingrediente_que_falta == 0) {
            printf("[Agente] Coloca en la mesa: PAPEL y FÓSFOROS.\n");
            usleep(150000);
            sem_post(&sem_fumador_tabaco); // Despierta al fumador con Tabaco
        } else if (ingrediente_que_falta == 1) {
            printf("[Agente] Coloca en la mesa: TABACO y FÓSFOROS.\n");
            usleep(150000);
            sem_post(&sem_fumador_papel);  // Despierta al fumador con Papel
        } else {
            printf("[Agente] Coloca en la mesa: TABACO y PAPEL.\n");
            usleep(150000);
            sem_post(&sem_fumador_fosforo);// Despierta al fumador con Fósforos
        }
    }
    return NULL;
}

// Fumador 1: Posee Tabaco
void* fumador_tabaco(void* arg) {
    while (1) {
        sem_wait(&sem_fumador_tabaco);
        printf("  -> [Fumador TABACO] Toma Papel y Fósforos. Arma cigarrillo y FUMA 🚬...\n");
        usleep(300000);
        printf("  -> [Fumador TABACO] Terminó de fumar. Avisa al Agente.\n");
        sem_post(&sem_agente);
    }
    return NULL;
}

// Fumador 2: Posee Papel
void* fumador_papel(void* arg) {
    while (1) {
        sem_wait(&sem_fumador_papel);
        printf("  -> [Fumador PAPEL] Toma Tabaco y Fósforos. Arma cigarrillo y FUMA 🚬...\n");
        usleep(300000);
        printf("  -> [Fumador PAPEL] Terminó de fumar. Avisa al Agente.\n");
        sem_post(&sem_agente);
    }
    return NULL;
}

// Fumador 3: Posee Fósforos
void* fumador_fosforo(void* arg) {
    while (1) {
        sem_wait(&sem_fumador_fosforo);
        printf("  -> [Fumador FÓSFORO] Toma Tabaco y Papel. Arma cigarrillo y FUMA 🚬...\n");
        usleep(300000);
        printf("  -> [Fumador FÓSFORO] Terminó de fumar. Avisa al Agente.\n");
        sem_post(&sem_agente);
    }
    return NULL;
}

int main(int argc, char* argv[]) {
    pthread_t th_agente, th_f1, th_f2, th_f3;

    srand(time(NULL));

    printf("====================================================\n");
    printf("   TP4 - Ejercicio 6: Fumadores de Cigarrillos      \n");
    printf("====================================================\n");

    // Inicialización de semáforos:
    // sem_agente inicia en 1 (mesa lista para colocar ingredientes)
    // fumadores inician en 0 (esperan sus ingredientes)
    sem_init(&sem_agente, 0, 1);
    sem_init(&sem_fumador_tabaco, 0, 0);
    sem_init(&sem_fumador_papel, 0, 0);
    sem_init(&sem_fumador_fosforo, 0, 0);

    // Creación de hilos fumadores
    pthread_create(&th_f1, NULL, fumador_tabaco, NULL);
    pthread_create(&th_f2, NULL, fumador_papel, NULL);
    pthread_create(&th_f3, NULL, fumador_fosforo, NULL);

    // Creación del hilo agente
    pthread_create(&th_agente, NULL, agente, NULL);

    // Esperar a que el agente complete las rondas
    pthread_join(th_agente, NULL);

    // Breve pausa para que el último fumador termine
    usleep(400000);

    // Cancelar hilos fumadores que quedan en loop infinito
    pthread_cancel(th_f1);
    pthread_cancel(th_f2);
    pthread_cancel(th_f3);

    // Destrucción de semáforos
    sem_destroy(&sem_agente);
    sem_destroy(&sem_fumador_tabaco);
    sem_destroy(&sem_fumador_papel);
    sem_destroy(&sem_fumador_fosforo);

    printf("\nSimulación de fumadores finalizada correctamente.\n");
    return EXIT_SUCCESS;
}

/**
 * ============================================================================
 * SISTEMAS OPERATIVOS - UNS (Trabajo Práctico N° 4: Sincronización)
 * Ejercicio 7 (Problema 7): El Barbero Dormilón (Dijkstra 1971)
 * ============================================================================
 * Consigna:
 * Sala de espera con N sillas. Si no hay clientes, el barbero duerme.
 * Cuando llega un cliente:
 * - Si todas las sillas están ocupadas, el cliente se va.
 * - Si hay sillas libres pero el barbero está ocupado, se sienta a esperar.
 * - Si el barbero está dormido, el cliente lo despierta.
 *
 * Sincronización con semáforos POSIX.
 *
 * Compilación:
 *   gcc -pthread ejercicio07_barbero_dormilon.c -o ejercicio07
 * Ejecución:
 *   ./ejercicio07
 * ============================================================================
 */

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <time.h>

#define NUM_SILLAS 3
#define TOTAL_CLIENTES 8

int esperando = 0; // Clientes sentados en la sala de espera

// Semáforos de sincronización
sem_t mutex;     // Protege el acceso a la variable 'esperando'
sem_t clientes;  // Cuenta clientes en espera (despierta al barbero si duerme)
sem_t barbero;   // Indica que el barbero está listo para cortar el pelo

// Hilo del Barbero
void* barbero_func(void* arg) {
    while (1) {
        printf("[Barbero] Zzz... Durmiendo en su sillón.\n");

        // 1. Espera a que llegue al menos un cliente
        sem_wait(&clientes);

        // 2. Sección Crítica: decrementar clientes en espera
        sem_wait(&mutex);
        esperando--;

        // 3. Notifica al cliente que pase al sillón de corte
        sem_post(&barbero);
        sem_post(&mutex);

        // 4. Realizar corte de pelo
        printf("[Barbero] ✂️  Cortando el pelo a un cliente...\n");
        usleep(350000); // 350ms de corte
        printf("[Barbero] ✓ Corte finalizado.\n");
    }
    return NULL;
}

// Hilo de cada Cliente
void* cliente_func(void* arg) {
    int id = *((int*)arg);

    usleep((rand() % 400 + 50) * 1000); // Llegan en momentos escalonados

    sem_wait(&mutex);
    printf("  [Cliente %d] Entra a la barbería (Sillas ocupadas: %d/%d).\n", id, esperando, NUM_SILLAS);

    if (esperando < NUM_SILLAS) {
        esperando++;
        printf("  [Cliente %d] Toma asiento en la sala de espera (Total esperando: %d).\n", id, esperando);

        // Despierta al barbero si estaba durmiendo
        sem_post(&clientes);
        sem_post(&mutex);

        // Espera a que el barbero lo llame al sillón de corte
        sem_wait(&barbero);
        printf("  [Cliente %d] Sentado en el sillón de barbero, recibiendo corte...\n", id);
    } else {
        // La sala de espera está llena: el cliente se retira
        printf("  [Cliente %d] ❌ Sala llena. Se retira sin cortarse el pelo.\n", id);
        sem_post(&mutex);
    }

    return NULL;
}

int main(int argc, char* argv[]) {
    pthread_t th_barbero;
    pthread_t th_clientes[TOTAL_CLIENTES];
    int ids[TOTAL_CLIENTES];

    srand(time(NULL));

    printf("====================================================\n");
    printf("   TP4 - Ejercicio 7: El Barbero Dormilón           \n");
    printf("   (Sillas de espera: %d | Total clientes: %d)      \n", NUM_SILLAS, TOTAL_CLIENTES);
    printf("====================================================\n\n");

    // Inicialización de semáforos
    sem_init(&mutex, 0, 1);
    sem_init(&clientes, 0, 0); // 0 clientes al inicio (barbero duerme)
    sem_init(&barbero, 0, 0);  // Barbero no listo hasta que atienda

    // Crear hilo barbero
    pthread_create(&th_barbero, NULL, barbero_func, NULL);

    // Crear hilos clientes
    for (int i = 0; i < TOTAL_CLIENTES; i++) {
        ids[i] = i + 1;
        pthread_create(&th_clientes[i], NULL, cliente_func, &ids[i]);
    }

    // Esperar a que todos los clientes pasen por la barbería
    for (int i = 0; i < TOTAL_CLIENTES; i++) {
        pthread_join(th_clientes[i], NULL);
    }

    // Pequeña espera para que el barbero termine el último corte si había alguno
    usleep(500000);
    pthread_cancel(th_barbero);

    // Destrucción de semáforos
    sem_destroy(&mutex);
    sem_destroy(&clientes);
    sem_destroy(&barbero);

    printf("\nJornada de la barbería finalizada.\n");
    return EXIT_SUCCESS;
}

/**
 * ============================================================================
 * SISTEMAS OPERATIVOS - UNS (Trabajo Práctico N° 4: Sincronización)
 * Ejercicio 8 (Problema 8): Lectores y Escritores con Semáforos
 * ============================================================================
 * Consigna:
 * Controlar el acceso a un archivo/recurso compartido permitiendo:
 * - Múltiples lectores leyendo simultáneamente.
 * - Un único escritor en forma totalmente exclusiva (ningún otro lector ni
 *   escritor puede estar activo a la vez).
 *
 * Implementación clásica con semáforos POSIX (Preferencia Lectores).
 *
 * Compilación:
 *   gcc -pthread ejercicio08_lectores_escritores_semaforos.c -o ejercicio08
 * Ejecución:
 *   ./ejercicio08
 * ============================================================================
 */

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define NUM_LECTORES   4
#define NUM_ESCRITORES 2
#define ITERACIONES    2

int dato_compartido = 100; // Recurso compartido
int read_count = 0;        // Contador de lectores activos en la base de datos

sem_t mutex; // Protege la variable compartida 'read_count'
sem_t db;    // Exclusión mutua para el acceso al recurso 'dato_compartido'

// Hilo Lector
void* lector(void* arg) {
    int id = *((int*)arg);

    for (int i = 1; i <= ITERACIONES; i++) {
        usleep((rand() % 300) * 1000);

        // --- ENTRADA AL RECURSO ---
        sem_wait(&mutex);
        read_count++;
        // El primer lector bloquea a los escritores
        if (read_count == 1) {
            sem_wait(&db);
        }
        sem_post(&mutex);

        // --- SECCIÓN DE LECTURA (concurrente entre lectores) ---
        printf("  [Lector %d] Leyendo dato: %d (Lectores concurrentes activos: %d)\n",
               id, dato_compartido, read_count);
        usleep(200000); // Simula tiempo de lectura

        // --- SALIDA DEL RECURSO ---
        sem_wait(&mutex);
        read_count--;
        // El último lector libera el recurso para que los escritores puedan entrar
        if (read_count == 0) {
            sem_post(&db);
        }
        sem_post(&mutex);
    }
    return NULL;
}

// Hilo Escritor
void* escritor(void* arg) {
    int id = *((int*)arg);

    for (int i = 1; i <= ITERACIONES; i++) {
        usleep((rand() % 400 + 100) * 1000);

        // El escritor requiere exclusión mutua total
        sem_wait(&db);

        // --- SECCIÓN DE ESCRITURA EXCLUSIVA ---
        dato_compartido += 10;
        printf(">>> [Escritor %d] Modificando dato compartido a: %d (Exclusión total activa)\n",
               id, dato_compartido);
        usleep(300000); // Simula tiempo de escritura
        printf(">>> [Escritor %d] Escritura finalizada.\n", id);

        sem_post(&db);
    }
    return NULL;
}

int main(int argc, char* argv[]) {
    pthread_t th_lectores[NUM_LECTORES];
    pthread_t th_escritores[NUM_ESCRITORES];
    int id_l[NUM_LECTORES], id_e[NUM_ESCRITORES];

    srand(time(NULL));

    printf("====================================================\n");
    printf("   TP4 - Ejercicio 8: Lectores y Escritores (Sem)   \n");
    printf("   (%d Lectores | %d Escritores)                     \n", NUM_LECTORES, NUM_ESCRITORES);
    printf("====================================================\n\n");

    // Inicialización de semáforos
    sem_init(&mutex, 0, 1);
    sem_init(&db, 0, 1);

    // Crear hilos lectores
    for (int i = 0; i < NUM_LECTORES; i++) {
        id_l[i] = i + 1;
        pthread_create(&th_lectores[i], NULL, lector, &id_l[i]);
    }

    // Crear hilos escritores
    for (int i = 0; i < NUM_ESCRITORES; i++) {
        id_e[i] = i + 1;
        pthread_create(&th_escritores[i], NULL, escritor, &id_e[i]);
    }

    // Esperar finalización
    for (int i = 0; i < NUM_LECTORES; i++) pthread_join(th_lectores[i], NULL);
    for (int i = 0; i < NUM_ESCRITORES; i++) pthread_join(th_escritores[i], NULL);

    // Limpieza
    sem_destroy(&mutex);
    sem_destroy(&db);

    printf("\nValor final del dato compartido = %d\n", dato_compartido);
    printf("Ejecución finalizada sin condiciones de carrera.\n");
    return EXIT_SUCCESS;
}

/**
 * ============================================================================
 * SISTEMAS OPERATIVOS - UNS (Trabajo Práctico N° 4: Sincronización)
 * Ejercicio 9 (Problema 9): Lectores - Escritores con Monitores (C POSIX)
 * ============================================================================
 * Consigna:
 * Implementar el monitor de lectores y escritores propuesto en la cátedra
 * utilizando primitivas POSIX (pthread_mutex_t y pthread_cond_t).
 *
 * Características del Monitor:
 * - Prioridad a Escritores: Si un escritor está en cola, los nuevos lectores
 *   esperan para evitar que un flujo constante de lectores bloquee al escritor.
 * - Variables de condición: ok_leer y ok_escribir.
 * - Métodos de entrada: inicio_leer(), fin_leer(), inicio_escribir(), fin_escribir().
 *
 * Compilación:
 *   gcc -pthread ejercicio09_lectores_escritores_monitores.c -o ejercicio09
 * Ejecución:
 *   ./ejercicio09
 * ============================================================================
 */

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

// Estructura del Monitor Lector - Escritor
typedef struct {
    pthread_mutex_t lock;      // Exclusión mutua interna del monitor
    pthread_cond_t  ok_leer;    // Condición para esperar a leer
    pthread_cond_t  ok_escribir;// Condición para esperar a escribir

    int lecto_cant;             // Cantidad de lectores activos
    int escribiendo;            // 1 si hay un escritor activo, 0 si no
    int escritores_esperando;   // Cantidad de escritores en cola (equivale a !empty(ok_escribir))
} MonitorLectorEscritor;

MonitorLectorEscritor monitor;
int dato_compartido = 50;

// Inicialización del Monitor
void monitor_init(MonitorLectorEscritor* m) {
    pthread_mutex_init(&m->lock, NULL);
    pthread_cond_init(&m->ok_leer, NULL);
    pthread_cond_init(&m->ok_escribir, NULL);
    m->lecto_cant = 0;
    m->escribiendo = 0;
    m->escritores_esperando = 0;
}

// Destrucción del Monitor
void monitor_destroy(MonitorLectorEscritor* m) {
    pthread_mutex_destroy(&m->lock);
    pthread_cond_destroy(&m->ok_leer);
    pthread_cond_destroy(&m->ok_escribir);
}

// Método de entrada: inicio_leer
void inicio_leer(MonitorLectorEscritor* m) {
    pthread_mutex_lock(&m->lock);

    // Si alguien está escribiendo O hay escritores esperando (prioridad escritores), esperar
    while (m->escribiendo || m->escritores_esperando > 0) {
        pthread_cond_wait(&m->ok_leer, &m->lock);
    }

    m->lecto_cant++;
    // En cascada despierta a otros lectores que puedan estar esperando
    pthread_cond_signal(&m->ok_leer);

    pthread_mutex_unlock(&m->lock);
}

// Método de entrada: fin_leer
void fin_leer(MonitorLectorEscritor* m) {
    pthread_mutex_lock(&m->lock);

    m->lecto_cant--;
    // Si fue el último lector, le da paso a un escritor en espera
    if (m->lecto_cant == 0) {
        pthread_cond_signal(&m->ok_escribir);
    }

    pthread_mutex_unlock(&m->lock);
}

// Método de entrada: inicio_escribir
void inicio_escribir(MonitorLectorEscritor* m) {
    pthread_mutex_lock(&m->lock);

    m->escritores_esperando++;

    // Debe esperar si hay lectores activos O si otro escritor está escribiendo
    while (m->lecto_cant != 0 || m->escribiendo) {
        pthread_cond_wait(&m->ok_escribir, &m->lock);
    }

    m->escritores_esperando--;
    m->escribiendo = 1;

    pthread_mutex_unlock(&m->lock);
}

// Método de entrada: fin_escribir
void fin_escribir(MonitorLectorEscritor* m) {
    pthread_mutex_lock(&m->lock);

    m->escribiendo = 0;

    // Política del monitor: si hay escritores esperando, avisa a otro escritor; si no, a los lectores
    if (m->escritores_esperando > 0) {
        pthread_cond_signal(&m->ok_escribir);
    } else {
        pthread_cond_broadcast(&m->ok_leer);
    }

    pthread_mutex_unlock(&m->lock);
}

// Hilo Lector
void* lector_hilo(void* arg) {
    int id = *((int*)arg);
    for (int i = 0; i < 2; i++) {
        usleep((rand() % 250) * 1000);

        inicio_leer(&monitor);
        printf("  [Monitor Lector %d] Leyendo dato: %d (Lectores activos en monitor: %d)\n",
               id, dato_compartido, monitor.lecto_cant);
        usleep(150000);
        fin_leer(&monitor);
    }
    return NULL;
}

// Hilo Escritor
void* escritor_hilo(void* arg) {
    int id = *((int*)arg);
    for (int i = 0; i < 2; i++) {
        usleep((rand() % 350 + 50) * 1000);

        inicio_escribir(&monitor);
        dato_compartido += 5;
        printf(">>> [Monitor Escritor %d] Escribiendo nuevo dato: %d (Exclusivo)\n", id, dato_compartido);
        usleep(200000);
        fin_escribir(&monitor);
    }
    return NULL;
}

int main(int argc, char* argv[]) {
    pthread_t l[4], e[2];
    int id_l[4], id_e[2];

    srand(time(NULL));

    printf("====================================================\n");
    printf("   TP4 - Ejercicio 9: Lectores-Escritores (Monitor) \n");
    printf("   (Implementación POSIX mutex + condition vars)    \n");
    printf("====================================================\n\n");

    monitor_init(&monitor);

    for (int i = 0; i < 4; i++) {
        id_l[i] = i + 1;
        pthread_create(&l[i], NULL, lector_hilo, &id_l[i]);
    }
    for (int i = 0; i < 2; i++) {
        id_e[i] = i + 1;
        pthread_create(&e[i], NULL, escritor_hilo, &id_e[i]);
    }

    for (int i = 0; i < 4; i++) pthread_join(l[i], NULL);
    for (int i = 0; i < 2; i++) pthread_join(e[i], NULL);

    monitor_destroy(&monitor);

    printf("\nEjecución con monitor completada con éxito. Dato final: %d\n", dato_compartido);
    return EXIT_SUCCESS;
}

/**
 * ============================================================================
 * SISTEMAS OPERATIVOS - UNS (Trabajo Práctico N° 4: Sincronización)
 * Ejercicio 10 (Problema 10): Productor - Consumidor con Monitores
 * ============================================================================
 * Consigna:
 * Implementar el problema del Productor-Consumidor con buffer acotado
 * utilizando la abstracción de Monitores (simulado en C con pthread_mutex_t
 * y pthread_cond_t con las condiciones no_lleno y no_vacio).
 *
 * Compilación:
 *   gcc -pthread ejercicio10_productor_consumidor_monitores.c -o ejercicio10
 * Ejecución:
 *   ./ejercicio10
 * ============================================================================
 */

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

#define BUFFER_SIZE 5
#define ITEMS_POR_PRODUCTOR 6
#define NUM_PRODUCTORES 2
#define NUM_CONSUMIDORES 2

// Estructura que encapsula el Monitor Productor-Consumidor
typedef struct {
    int buffer[BUFFER_SIZE];
    int in;
    int out;
    int count;

    pthread_mutex_t lock;      // Exclusión mutua interna del monitor
    pthread_cond_t  no_lleno;  // Espera si el buffer está lleno (count == BUFFER_SIZE)
    pthread_cond_t  no_vacio;  // Espera si el buffer está vacío (count == 0)
} MonitorPC;

MonitorPC mon;

// Inicialización del Monitor
void monitor_pc_init(MonitorPC* m) {
    m->in = 0;
    m->out = 0;
    m->count = 0;
    pthread_mutex_init(&m->lock, NULL);
    pthread_cond_init(&m->no_lleno, NULL);
    pthread_cond_init(&m->no_vacio, NULL);
}

// Destrucción del Monitor
void monitor_pc_destroy(MonitorPC* m) {
    pthread_mutex_destroy(&m->lock);
    pthread_cond_destroy(&m->no_lleno);
    pthread_cond_destroy(&m->no_vacio);
}

// Método de entrada al Monitor: insertar elemento
void monitor_pc_insertar(MonitorPC* m, int item, int prod_id) {
    pthread_mutex_lock(&m->lock);

    // Mientras el buffer esté lleno, suspender en condición no_lleno
    while (m->count == BUFFER_SIZE) {
        printf("  [Productor %d] Buffer LLENO (%d/%d). Esperando en no_lleno...\n",
               prod_id, m->count, BUFFER_SIZE);
        pthread_cond_wait(&m->no_lleno, &m->lock);
    }

    // Inserción en el buffer
    m->buffer[m->in] = item;
    m->in = (m->in + 1) % BUFFER_SIZE;
    m->count++;
    printf("[Productor %d] -> Insertó %3d (Ocupación: %d/%d)\n", prod_id, item, m->count, BUFFER_SIZE);

    // Notificar a los consumidores que el buffer ya no está vacío
    pthread_cond_signal(&m->no_vacio);

    pthread_mutex_unlock(&m->lock);
}

// Método de entrada al Monitor: remover elemento
int monitor_pc_remover(MonitorPC* m, int cons_id) {
    pthread_mutex_lock(&m->lock);

    // Mientras el buffer esté vacío, suspender en condición no_vacio
    while (m->count == 0) {
        printf("    [Consumidor %d] Buffer VACÍO (0/%d). Esperando en no_vacio...\n",
               cons_id, BUFFER_SIZE);
        pthread_cond_wait(&m->no_vacio, &m->lock);
    }

    // Extracción del buffer
    int item = m->buffer[m->out];
    m->out = (m->out + 1) % BUFFER_SIZE;
    m->count--;
    printf("    [Consumidor %d] <- Extrajo %3d (Ocupación: %d/%d)\n", cons_id, item, m->count, BUFFER_SIZE);

    // Notificar a los productores que hay un nuevo espacio libre
    pthread_cond_signal(&m->no_lleno);

    pthread_mutex_unlock(&m->lock);
    return item;
}

// Hilo Productor
void* productor_hilo(void* arg) {
    int id = *((int*)arg);
    for (int i = 1; i <= ITEMS_POR_PRODUCTOR; i++) {
        int item = (id * 100) + i;
        monitor_pc_insertar(&mon, item, id);
        usleep((rand() % 150 + 50) * 1000);
    }
    return NULL;
}

// Hilo Consumidor
void* consumidor_hilo(void* arg) {
    int id = *((int*)arg);
    int total_a_consumir = (NUM_PRODUCTORES * ITEMS_POR_PRODUCTOR) / NUM_CONSUMIDORES;
    for (int i = 1; i <= total_a_consumir; i++) {
        int item = monitor_pc_remover(&mon, id);
        (void)item;
        usleep((rand() % 250 + 100) * 1000);
    }
    return NULL;
}

int main(int argc, char* argv[]) {
    pthread_t prods[NUM_PRODUCTORES], cons[NUM_CONSUMIDORES];
    int id_p[NUM_PRODUCTORES], id_c[NUM_CONSUMIDORES];

    srand(time(NULL));

    printf("====================================================\n");
    printf("   TP4 - Ejercicio 10: Productor-Consumidor (Monitor)\n");
    printf("   (Buffer: %d | Productores: %d | Consumidores: %d)\n",
           BUFFER_SIZE, NUM_PRODUCTORES, NUM_CONSUMIDORES);
    printf("====================================================\n\n");

    monitor_pc_init(&mon);

    for (int i = 0; i < NUM_PRODUCTORES; i++) {
        id_p[i] = i + 1;
        pthread_create(&prods[i], NULL, productor_hilo, &id_p[i]);
    }
    for (int i = 0; i < NUM_CONSUMIDORES; i++) {
        id_c[i] = i + 1;
        pthread_create(&cons[i], NULL, consumidor_hilo, &id_c[i]);
    }

    for (int i = 0; i < NUM_PRODUCTORES; i++) pthread_join(prods[i], NULL);
    for (int i = 0; i < NUM_CONSUMIDORES; i++) pthread_join(cons[i], NULL);

    monitor_pc_destroy(&mon);

    printf("\nTodos los elementos fueron producidos y consumidos a través del monitor.\n");
    return EXIT_SUCCESS;
}

/**
 * ============================================================================
 * SISTEMAS OPERATIVOS - UNS (Trabajo Práctico N° 4: Sincronización)
 * Ejercicio 11 (Problema 11): El Oso y las Abejas
 * ============================================================================
 * Consigna:
 * Se tienen N abejas y un oso hambriento. Comparten un tarro de miel con
 * capacidad para M porciones.
 * - Inicialmente el tarro está vacío.
 * - Cada abeja produce 1 porción y la coloca en el tarro.
 * - La abeja que coloca la porción M despierta al oso.
 * - El oso despierta, se come toda la miel (porciones = 0) y vuelve a dormir.
 * - Las abejas no pueden agregar miel mientras el oso come.
 *
 * Sincronización implementada con semáforos POSIX.
 *
 * Compilación:
 *   gcc -pthread ejercicio11_oso_abejas.c -o ejercicio11
 * Ejecución:
 *   ./ejercicio11
 * ============================================================================
 */

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define M 5              // Capacidad del tarro de miel
#define NUM_ABEJAS 3     // Cantidad de abejas concurrentes
#define RONDAS_OSO 3     // El oso comerá 3 tarros completos para la prueba

int porciones_en_tarro = 0;

sem_t mutex_tarro;   // Exclusión mutua para acceder al tarro
sem_t sem_oso;       // Despierta al oso cuando el tarro se llena (inicia en 0)
sem_t sem_tarro_vacio;// Señal del oso a las abejas avisando que el tarro quedó vacío (inicia en 1)

// Hilo del Oso
void* oso_hilo(void* arg) {
    for (int r = 1; r <= RONDAS_OSO; r++) {
        printf("[Oso] Zzz... Durmiendo a la espera de miel.\n");

        // Espera a que una abeja lo despierte (cuando se llena el tarro)
        sem_wait(&sem_oso);

        printf("\n>>> [Oso] 🐻 ¡DESPERTÓ! El tarro tiene %d porciones de miel.\n", porciones_en_tarro);
        usleep(300000); // 300ms comiendo

        porciones_en_tarro = 0;
        printf(">>> [Oso] 🍯 Se comió toda la miel. El tarro vuelve a estar VACÍO (0/%d).\n\n", M);

        // Habilita nuevamente a las abejas para que puedan poner miel
        sem_post(&sem_tarro_vacio);
    }
    return NULL;
}

// Hilo de cada Abeja
void* abeja_hilo(void* arg) {
    int id = *((int*)arg);

    while (1) {
        // Simular tiempo produciendo miel
        usleep((rand() % 200 + 50) * 1000);

        // Asegurarse de que el tarro no esté en proceso de ser comido por el oso
        sem_wait(&mutex_tarro);

        porciones_en_tarro++;
        printf("  [Abeja %d] 🐝 Colocó 1 porción de miel. (Tarro: %d/%d)\n",
               id, porciones_en_tarro, M);

        if (porciones_en_tarro == M) {
            printf("  [Abeja %d] ⭐ ¡El tarro está LLENO! Despertando al oso...\n", id);
            // Despierta al oso
            sem_post(&sem_oso);
            // El mutex_tarro se retiene implícitamente o se espera a que el oso vacíe
            sem_wait(&sem_tarro_vacio); // Espera a que el oso termine de comer
            sem_post(&mutex_tarro);
        } else {
            sem_post(&mutex_tarro);
        }
    }
    return NULL;
}

int main(int argc, char* argv[]) {
    pthread_t th_oso;
    pthread_t th_abejas[NUM_ABEJAS];
    int ids[NUM_ABEJAS];

    srand(time(NULL));

    printf("====================================================\n");
    printf("   TP4 - Ejercicio 11: El Oso y las Abejas          \n");
    printf("   (Capacidad M: %d | Abejas: %d | Rondas Oso: %d)   \n", M, NUM_ABEJAS, RONDAS_OSO);
    printf("====================================================\n\n");

    // Inicialización de semáforos
    sem_init(&mutex_tarro, 0, 1);
    sem_init(&sem_oso, 0, 0);
    sem_init(&sem_tarro_vacio, 0, 0);

    // Crear hilo oso
    pthread_create(&th_oso, NULL, oso_hilo, NULL);

    // Crear hilos abejas
    for (int i = 0; i < NUM_ABEJAS; i++) {
        ids[i] = i + 1;
        pthread_create(&th_abejas[i], NULL, abeja_hilo, &ids[i]);
    }

    // Esperar a que el oso complete sus rondas de comida
    pthread_join(th_oso, NULL);

    // Cancelar hilos de abejas que corren en loop infinito
    for (int i = 0; i < NUM_ABEJAS; i++) {
        pthread_cancel(th_abejas[i]);
    }

    // Destrucción de semáforos
    sem_destroy(&mutex_tarro);
    sem_destroy(&sem_oso);
    sem_destroy(&sem_tarro_vacio);

    printf("Simulación del oso y las abejas completada exitosamente.\n");
    return EXIT_SUCCESS;
}

/**
 * ============================================================================
 * SISTEMAS OPERATIVOS - UNS (Trabajo Práctico N° 4: Sincronización)
 * Ejercicio 12 (Problema 12): Limitación de Conexiones en Servidor
 * ============================================================================
 * Consigna:
 * Los servidores pueden diseñarse para limitar el número de conexiones abiertas.
 * Por ejemplo, autorizar sólo N conexiones simultáneas de tipo socket.
 * En cuanto se alcancen las N conexiones, el servidor no aceptará otra
 * entrante hasta que una existente se libere.
 *
 * Implementación con un semáforo contador POSIX (sem_t):
 * - sem_init(&limite_conexiones, 0, N);
 * - El despachador invoca sem_wait(&limite_conexiones) antes de atender.
 * - Cada worker thread atiende al cliente y al cerrar invoca sem_post.
 *
 * Compilación:
 *   gcc -pthread ejercicio12_limite_conexiones.c -o ejercicio12
 * Ejecución:
 *   ./ejercicio12
 * ============================================================================
 */

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define MAX_CONEXIONES_SIMULTANEAS 3
#define TOTAL_SOLICITUDES          10

sem_t limite_conexiones; // Semáforo contador inicializado en MAX_CONEXIONES_SIMULTANEAS
int conexiones_activas = 0;
pthread_mutex_t mutex_cont; // Solo para llevar estadística segura de conexiones activas

// Función que atiende a una conexión de cliente en un hilo separado
void* atender_cliente(void* arg) {
    int id = *((int*)arg);

    pthread_mutex_lock(&mutex_cont);
    conexiones_activas++;
    printf("  [Worker Conexión #%02d] -> Conectado. Conexiones activas: %d/%d\n",
           id, conexiones_activas, MAX_CONEXIONES_SIMULTANEAS);
    pthread_mutex_unlock(&mutex_cont);

    // Simula procesamiento de la petición del cliente (E/S o cálculo)
    usleep((rand() % 300 + 200) * 1000); // 200ms a 500ms

    pthread_mutex_lock(&mutex_cont);
    conexiones_activas--;
    printf("  [Worker Conexión #%02d] <- Cerrando socket. Conexiones activas: %d/%d\n",
           id, conexiones_activas, MAX_CONEXIONES_SIMULTANEAS);
    pthread_mutex_unlock(&mutex_cont);

    // CRÍTICO: Libera el slot de conexión para permitir que entre la siguiente
    sem_post(&limite_conexiones);

    free(arg);
    return NULL;
}

int main(int argc, char* argv[]) {
    pthread_t hilos[TOTAL_SOLICITUDES];

    srand(time(NULL));

    printf("====================================================\n");
    printf("   TP4 - Ejercicio 12: Limitación de Conexiones     \n");
    printf("   (Límite: %d simultáneas | Solicitudes: %d)       \n",
           MAX_CONEXIONES_SIMULTANEAS, TOTAL_SOLICITUDES);
    printf("====================================================\n\n");

    // Inicialización del semáforo contador con el límite N de conexiones
    sem_init(&limite_conexiones, 0, MAX_CONEXIONES_SIMULTANEAS);
    pthread_mutex_init(&mutex_cont, NULL);

    printf("[Servidor] Iniciando bucle despachador de conexiones...\n\n");

    for (int i = 1; i <= TOTAL_SOLICITUDES; i++) {
        printf("[Dispatcher] Recibida solicitud #%02d. Verificando disponibilidad...\n", i);

        // Si ya hay N conexiones activas, el semáforo está en 0 y el dispatcher se BLOQUEA aquí
        sem_wait(&limite_conexiones);

        printf("[Dispatcher] ✓ Slot disponible otorgado para conexión #%02d.\n", i);

        int* id = malloc(sizeof(int));
        *id = i;
        pthread_create(&hilos[i - 1], NULL, atender_cliente, id);

        usleep(80000); // Pequeña pausa entre llegadas de clientes
    }

    // Esperar a que todos los workers finalicen
    for (int i = 0; i < TOTAL_SOLICITUDES; i++) {
        pthread_join(hilos[i], NULL);
    }

    sem_destroy(&limite_conexiones);
    pthread_mutex_destroy(&mutex_cont);

    printf("\nTodas las solicitudes fueron atendidas respetando el límite estricto de %d conexiones.\n",
           MAX_CONEXIONES_SIMULTANEAS);
    return EXIT_SUCCESS;
}

/**
 * ============================================================================
 * SISTEMAS OPERATIVOS - UNS (Trabajo Práctico N° 4: Sincronización)
 * Ejercicio 13 (Problema 13): Usuarios Compartiendo 2 Impresoras
 * ============================================================================
 * Consigna:
 * N usuarios (hilos) comparten 2 impresoras.
 * - requerir_impresora(): Espera hasta que haya una libre y retorna su ID (0 o 1).
 * - liberar_impresora(id): Libera la impresora y despierta al siguiente usuario.
 *
 * Inciso a: Sincronización con semáforos POSIX para asignar impresoras libres.
 * Inciso b: Asignación por PRIORIDAD ÚNICA al usuario de mayor prioridad en espera.
 *
 * Compilación:
 *   gcc -pthread ejercicio13_impresoras_compartidas.c -o ejercicio13
 * Ejecución:
 *   ./ejercicio13
 * ============================================================================
 */

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define NUM_IMPRESORAS 2
#define NUM_USUARIOS   6

// ----------------------------------------------------------------------------
// PARTE A: ASIGNACIÓN SIMPLE CON SEMÁFOROS
// ----------------------------------------------------------------------------
typedef struct {
    sem_t impresoras_disponibles; // Contador: inicia en 2
    sem_t mutex_estado;           // Mutex binario para consultar/marcar libre[]
    int libre[NUM_IMPRESORAS];    // 1 si está libre, 0 si ocupada
} ServidorImpresionA;

ServidorImpresionA servA;

void servidor_a_init(ServidorImpresionA* s) {
    sem_init(&s->impresoras_disponibles, 0, NUM_IMPRESORAS);
    sem_init(&s->mutex_estado, 0, 1);
    for (int i = 0; i < NUM_IMPRESORAS; i++) s->libre[i] = 1;
}

int requerir_impresora_a(ServidorImpresionA* s, int usuario_id) {
    // 1. Espera a que haya al menos una impresora libre en total
    sem_wait(&s->impresoras_disponibles);

    // 2. Sección Crítica: identificar cuál de las dos impresoras está libre
    sem_wait(&s->mutex_estado);
    int id_impresora = -1;
    for (int i = 0; i < NUM_IMPRESORAS; i++) {
        if (s->libre[i]) {
            s->libre[i] = 0;
            id_impresora = i;
            break;
        }
    }
    sem_post(&s->mutex_estado);

    printf("  [Usuario %d] -> Obtuvo Impresora #%d libre.\n", usuario_id, id_impresora);
    return id_impresora;
}

void liberar_impresora_a(ServidorImpresionA* s, int id_impresora, int usuario_id) {
    sem_wait(&s->mutex_estado);
    s->libre[id_impresora] = 1;
    printf("  [Usuario %d] <- Liberó Impresora #%d.\n", usuario_id, id_impresora);
    sem_post(&s->mutex_estado);

    // Incrementa la disponibilidad para despertar al siguiente usuario
    sem_post(&s->impresoras_disponibles);
}

// ----------------------------------------------------------------------------
// PARTE B: ASIGNACIÓN POR PRIORIDAD ÚNICA
// ----------------------------------------------------------------------------
typedef struct {
    int usuario_id;
    int prioridad;          // Mayor valor = Mayor prioridad
    int id_impresora_asignada;
    sem_t sem_privado;      // Bloquea al hilo hasta que se le asigne impresora
    int esperando;
} Solicitante;

typedef struct {
    pthread_mutex_t lock;
    int libre[NUM_IMPRESORAS];
    Solicitante solicitantes[NUM_USUARIOS];
} ServidorPrioridadB;

ServidorPrioridadB servB;

void servidor_b_init(ServidorPrioridadB* s) {
    pthread_mutex_init(&s->lock, NULL);
    for (int i = 0; i < NUM_IMPRESORAS; i++) s->libre[i] = 1;
    for (int i = 0; i < NUM_USUARIOS; i++) {
        s->solicitantes[i].usuario_id = i;
        s->solicitantes[i].prioridad = (i + 1) * 10; // Prioridades únicas: 10, 20, 30, 40, 50, 60
        s->solicitantes[i].esperando = 0;
        s->solicitantes[i].id_impresora_asignada = -1;
        sem_init(&s->solicitantes[i].sem_privado, 0, 0);
    }
}

int requerir_impresora_b(ServidorPrioridadB* s, int usuario_id) {
    pthread_mutex_lock(&s->lock);

    // Si hay una impresora libre de inmediato, la toma
    for (int i = 0; i < NUM_IMPRESORAS; i++) {
        if (s->libre[i]) {
            s->libre[i] = 0;
            printf("  [Usuario %d | Prioridad %d] -> Impresora #%d libre directa.\n",
                   usuario_id, s->solicitantes[usuario_id].prioridad, i);
            pthread_mutex_unlock(&s->lock);
            return i;
        }
    }

    // Ambas impresoras ocupadas: se registra en espera
    s->solicitantes[usuario_id].esperando = 1;
    printf("  [Usuario %d | Prioridad %d] En espera. Ambas impresoras ocupadas.\n",
           usuario_id, s->solicitantes[usuario_id].prioridad);
    pthread_mutex_unlock(&s->lock);

    // Espera en su semáforo privado
    sem_wait(&s->solicitantes[usuario_id].sem_privado);

    return s->solicitantes[usuario_id].id_impresora_asignada;
}

void liberar_impresora_b(ServidorPrioridadB* s, int id_impresora, int usuario_id) {
    pthread_mutex_lock(&s->lock);

    printf("  [Usuario %d | Prioridad %d] <- Liberó Impresora #%d.\n",
           usuario_id, s->solicitantes[usuario_id].prioridad, id_impresora);

    // Buscar entre los usuarios en espera aquel con MAYOR PRIORIDAD
    int mejor_candidato = -1;
    int max_prioridad = -1;

    for (int i = 0; i < NUM_USUARIOS; i++) {
        if (s->solicitantes[i].esperando) {
            if (s->solicitantes[i].prioridad > max_prioridad) {
                max_prioridad = s->solicitantes[i].prioridad;
                mejor_candidato = i;
            }
        }
    }

    if (mejor_candidato != -1) {
        // Se le asigna la impresora directamente al usuario más prioritario
        s->solicitantes[mejor_candidato].esperando = 0;
        s->solicitantes[mejor_candidato].id_impresora_asignada = id_impresora;
        printf("  >>> Servidor asigna Impresora #%d al Usuario %d por MAYOR PRIORIDAD (%d)\n",
               id_impresora, mejor_candidato, max_prioridad);
        sem_post(&s->solicitantes[mejor_candidato].sem_privado);
    } else {
        // No hay nadie esperando, la impresora queda libre
        s->libre[id_impresora] = 1;
    }

    pthread_mutex_unlock(&s->lock);
}

// Rutina de usuario para Parte A
void* usuario_hilo_a(void* arg) {
    int id = *((int*)arg);
    usleep((rand() % 200) * 1000);

    int id_imp = requerir_impresora_a(&servA, id);
    usleep(200000); // Imprimiendo...
    liberar_impresora_a(&servA, id_imp, id);

    return NULL;
}

// Rutina de usuario para Parte B
void* usuario_hilo_b(void* arg) {
    int id = *((int*)arg);
    usleep((rand() % 150) * 1000);

    int id_imp = requerir_impresora_b(&servB, id);
    usleep(250000); // Imprimiendo...
    liberar_impresora_b(&servB, id_imp, id);

    return NULL;
}

int main(int argc, char* argv[]) {
    pthread_t th[NUM_USUARIOS];
    int ids[NUM_USUARIOS];

    srand(time(NULL));

    printf("====================================================\n");
    printf("   TP4 - Ejercicio 13: 2 Impresoras Compartidas     \n");
    printf("====================================================\n\n");

    // Ejecución Parte A
    printf("--- PARTE A: Asignación estándar con semáforos ---\n");
    servidor_a_init(&servA);
    for (int i = 0; i < NUM_USUARIOS; i++) {
        ids[i] = i + 1;
        pthread_create(&th[i], NULL, usuario_hilo_a, &ids[i]);
    }
    for (int i = 0; i < NUM_USUARIOS; i++) pthread_join(th[i], NULL);
    sem_destroy(&servA.impresoras_disponibles);
    sem_destroy(&servA.mutex_estado);

    // Ejecución Parte B
    printf("\n--- PARTE B: Asignación por PRIORIDAD ÚNICA ---\n");
    servidor_b_init(&servB);
    for (int i = 0; i < NUM_USUARIOS; i++) {
        ids[i] = i;
        pthread_create(&th[i], NULL, usuario_hilo_b, &ids[i]);
    }
    for (int i = 0; i < NUM_USUARIOS; i++) pthread_join(th[i], NULL);
    pthread_mutex_destroy(&servB.lock);
    for (int i = 0; i < NUM_USUARIOS; i++) {
        sem_destroy(&servB.solicitantes[i].sem_privado);
    }

    printf("\nTodos los usuarios completaron sus impresiones.\n");
    return EXIT_SUCCESS;
}

steps.explanation:
**Grafo:** $I \to p1 \to \{p2, p3, p4 \to p5\} \to p6 \to I$

Se requiere sincronizar para que cicle indefinidamente con la menor cantidad de semáforos:

```c
semaphore s_I = 1;  // Permite iniciar la primera iteración
semaphore s_p1 = 0, s_p5 = 0, s_fin = 0;
int contador = 0;
semaphore mutex = 1;

// Proceso I
while(1) {
    wait(s_I);
    ejecutar_I();
    signal(s_p1);
}

// Proceso p1
while(1) {
    wait(s_p1);
    ejecutar_p1();
    signal(s_p2); signal(s_p3); signal(s_p4);
}

// Procesos concurrentes p2, p3 y rama p4->p5 que convergen en p6
// Al terminar p6, hace signal(s_I) cerrando el ciclo.
```

**a) Identificación de la Condición de Carrera:**
La variable compartida `numprocesses` es leída y modificada concurrentemente por `allocate_process()` y `release_process()`. Las operaciones `++numprocesses` y `--numprocesses` constan de 3 instrucciones máquina (Lectura, Modificación, Escritura). Si dos procesos ejecutan estas funciones a la vez, se produce una condición de carrera: una actualización puede sobreescribir a la otra o superar el límite `MAX_PROCESSES`.

**b) Solución con Mutex:**
```c
mutex_t m;

int allocate_process() {
    int new_pid = -1;
    mutex_lock(&m);
    if (numprocesses < MAX_PROCESSES) {
        /* alocar recursos */
        ++numprocesses;
        new_pid = obtener_pid();
    }
    mutex_unlock(&m);
    return new_pid;
}

void release_process() {
    mutex_lock(&m);
    /* liberar recursos */
    --numprocesses;
    mutex_unlock(&m);
}
```

**c) Metodología para evitar la variable entera compartida:**
Se puede utilizar un **Semáforo Contador** inicializado en `MAX_PROCESSES` (`sem_t sem_procesos`).
- En `allocate_process()`: se invoca `sem_trywait(&sem_procesos)`. Si retorna éxito, hay cupo disponible.
- En `release_process()`: se invoca `sem_post(&sem_procesos)`.

steps.codeSnippet:
/**
 * ============================================================================
 * UNIVERSIDAD NACIONAL DEL SUR (UNS)
 * Departamento de Ciencias e Ingeniería de la Computación
 * Sistemas Operativos - Laboratorio de Sincronización
 *
 * Problema: Centro de Cómputos y Control de Licencias Especializadas
 * ============================================================================
 * Consigna:
 * - Se disponen un total de 20 licencias.
 * - Cada usuario puede requerir entre 1 y 3 licencias.
 * - Si consigue las licencias requeridas, realiza su trabajo.
 * - Al terminar guarda sus resultados en una base de datos compartida y
 *   por último libera las licencias utilizadas.
 * - Si no puede conseguir todas las licencias requeridas, se retira sin hacer nada.
 *
 * Compilación:
 *   gcc -Wall -Wextra -pthread -o centro_computos centro_computos.c
 * Ejecución:
 *   ./centro_computos [num_usuarios]
 * ============================================================================
 */

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

/* --- Parámetros de configuración del sistema --- */
#define TOTAL_LICENCIAS         20
#define MIN_LICENCIAS_REQ       1
#define MAX_LICENCIAS_REQ       3
#define NUM_USUARIOS_DEFAULT    30
#define ARCHIVO_BD              "resultados_bd.txt"

/* --- Estructura para registrar los datos en la Base de Datos Compartida --- */
typedef struct {
    int id_registro;
    int id_usuario;
    int licencias_utilizadas;
    int tiempo_computo_ms;
    char resultado[64];
    char timestamp[32];
} RegistroBD;

#define MAX_REGISTROS 1000
static RegistroBD base_de_datos[MAX_REGISTROS];
static int total_registros_bd = 0;

/* --- Variables de estado del Centro de Cómputos --- */
static int licencias_disponibles = TOTAL_LICENCIAS;

/* --- Herramientas de sincronización (Mutexes POSIX) --- */
/*
 * 1. mutex_licencias:
 *    Protege el contador de licencias disponibles y asegura que la consulta
 *    y asignación de licencias sea una operación atómica indivisible (Todo o Nada).
 */
static pthread_mutex_t mutex_licencias = PTHREAD_MUTEX_INITIALIZER;

/*
 * 2. mutex_bd:
 *    Garantiza exclusión mutua estricta al acceder a la base de datos compartida
 *    (tanto en memoria como en el archivo en disco), evitando condiciones de carrera.
 */
static pthread_mutex_t mutex_bd = PTHREAD_MUTEX_INITIALIZER;

/*
 * 3. mutex_pantalla:
 *    Evita que los mensajes por consola (stdout) de múltiples hilos se intercalen
 *    o rompan líneas visualmente durante la ejecución concurrente.
 */
static pthread_mutex_t mutex_pantalla = PTHREAD_MUTEX_INITIALIZER;

/* --- Métricas estadísticas globales --- */
static int total_solicitudes = 0;
static int usuarios_atendidos_exitosos = 0;
static int usuarios_rechazados = 0;

/* --- Función auxiliar para obtener timestamp formateado --- */
void obtener_tiempo_actual(char *buffer, size_t max_len) {
    time_t rawtime;
    struct tm *info_tiempo;
    time(&rawtime);
    info_tiempo = localtime(&rawtime);
    strftime(buffer, max_len, "%H:%M:%S", info_tiempo);
}

/* --- Función auxiliar para imprimir mensajes protegidos por mutex --- */
void log_evento(const char *color, const char *formato, int id, int val1, int val2) {
    char tiempo[32];
    obtener_tiempo_actual(tiempo, sizeof(tiempo));

    pthread_mutex_lock(&mutex_pantalla);
    printf("[%s] %s", tiempo, color);
    if (val1 == -1 && val2 == -1) {
        printf(formato, id);
    } else if (val2 == -1) {
        printf(formato, id, val1);
    } else {
        printf(formato, id, val1, val2);
    }
    printf("\033[0m\n");
    fflush(stdout);
    pthread_mutex_unlock(&mutex_pantalla);
}

/*
 * ----------------------------------------------------------------------------
 * Operación: Solicitar Licencias (No bloqueante, atómica / Todo o Nada)
 * Retorna:
 *   1 si consiguió TODAS las licencias solicitadas.
 *   0 si NO había suficientes licencias (se retira sin hacer nada).
 * ----------------------------------------------------------------------------
 */
int solicitar_licencias(int id_usuario, int cant_requerida) {
    int exito = 0;

    pthread_mutex_lock(&mutex_licencias);

    if (licencias_disponibles >= cant_requerida) {
        // Asignación atómica completa
        licencias_disponibles -= cant_requerida;
        exito = 1;
        log_evento("\033[1;32m", "USUARIO %02d | ADQUIRIÓ %d licencias. (Restan: %d libres)",
                   id_usuario, cant_requerida, licencias_disponibles);
    } else {
        // No hay suficientes licencias disponibles: RECHAZO INMEDIATO
        exito = 0;
        log_evento("\033[1;31m", "USUARIO %02d | RECHAZADO: Solicitó %d licencias pero solo hay %d. Se retira sin hacer nada.",
                   id_usuario, cant_requerida, licencias_disponibles);
    }

    pthread_mutex_unlock(&mutex_licencias);
    return exito;
}

/*
 * ----------------------------------------------------------------------------
 * Operación: Liberar Licencias
 * Devuelve las licencias utilizadas al pool del centro de cómputos.
 * ----------------------------------------------------------------------------
 */
void liberar_licencias(int id_usuario, int cant_liberar) {
    pthread_mutex_lock(&mutex_licencias);

    licencias_disponibles += cant_liberar;
    log_evento("\033[1;34m", "USUARIO %02d | LIBERÓ %d licencias. (Ahora hay: %d libres)",
               id_usuario, cant_liberar, licencias_disponibles);

    pthread_mutex_unlock(&mutex_licencias);
}

/*
 * ----------------------------------------------------------------------------
 * Operación: Guardar Resultados en la Base de Datos Compartida
 * Sección crítica protegida por mutex_bd.
 * ----------------------------------------------------------------------------
 */
void guardar_en_base_de_datos(int id_usuario, int licencias_usadas, int tiempo_ms, const char *resultado_calculo) {
    pthread_mutex_lock(&mutex_bd);

    // 1. Guardar en estructura de datos en memoria
    if (total_registros_bd < MAX_REGISTROS) {
        RegistroBD *reg = &base_de_datos[total_registros_bd];
        reg->id_registro = total_registros_bd + 1;
        reg->id_usuario = id_usuario;
        reg->licencias_utilizadas = licencias_usadas;
        reg->tiempo_computo_ms = tiempo_ms;
        strncpy(reg->resultado, resultado_calculo, sizeof(reg->resultado) - 1);
        obtener_tiempo_actual(reg->timestamp, sizeof(reg->timestamp));
        total_registros_bd++;
    }

    // 2. Persistir en archivo compartido en disco
    FILE *archivo = fopen(ARCHIVO_BD, "a");
    if (archivo != NULL) {
        char tiempo[32];
        obtener_tiempo_actual(tiempo, sizeof(tiempo));
        fprintf(archivo, "[%s] Registro #%d | Usuario: %02d | Licencias: %d | Duración: %d ms | Resultado: %s\n",
                tiempo, total_registros_bd, id_usuario, licencias_usadas, tiempo_ms, resultado_calculo);
        fclose(archivo);
    }

    log_evento("\033[1;35m", "USUARIO %02d | GUARDÓ resultados en BD compartida (Registro #%d)",
               id_usuario, total_registros_bd, -1);

    pthread_mutex_unlock(&mutex_bd);
}

/*
 * ----------------------------------------------------------------------------
 * Función del Hilo Usuario:
 * Modela el ciclo de vida completo de cada usuario del centro de cómputos.
 * ----------------------------------------------------------------------------
 */
void* hilo_usuario(void *arg) {
    int id_usuario = *((int*)arg);
    free(arg);

    // Cada usuario requiere entre 1 y 3 licencias
    int licencias_requeridas = (rand() % (MAX_LICENCIAS_REQ - MIN_LICENCIAS_REQ + 1)) + MIN_LICENCIAS_REQ;

    log_evento("\033[0;37m", "USUARIO %02d | Llega al centro de cómputos. Requiere %d licencias.",
               id_usuario, licencias_requeridas, -1);

    // Intento atómico de adquisición
    int conseguidas = solicitar_licencias(id_usuario, licencias_requeridas);

    if (!conseguidas) {
        // "Si no puede conseguir todas las licencias requeridas, se retira sin hacer nada."
        pthread_mutex_lock(&mutex_licencias);
        usuarios_rechazados++;
        pthread_mutex_unlock(&mutex_licencias);
        return NULL;
    }

    // "Si consigue las licencias requeridas, realiza su trabajo."
    pthread_mutex_lock(&mutex_licencias);
    usuarios_atendidos_exitosos++;
    pthread_mutex_unlock(&mutex_licencias);

    // Simulación del cómputo con las licencias adquiridas (entre 100 ms y 400 ms)
    int tiempo_computo_ms = 100 + (rand() % 301);
    log_evento("\033[0;33m", "USUARIO %02d | Procesando trabajo científico (%d ms)...",
               id_usuario, tiempo_computo_ms, -1);
    usleep(tiempo_computo_ms * 1000);

    // Generar resultado ficticio
    char resultado[64];
    snprintf(resultado, sizeof(resultado), "SIM_OK_VAL_%.2f", (rand() % 10000) / 100.0);

    // "Al terminar guarda sus resultados en una base de datos compartida..."
    guardar_en_base_de_datos(id_usuario, licencias_requeridas, tiempo_computo_ms, resultado);

    // "... y por último libera las licencias utilizadas."
    liberar_licencias(id_usuario, licencias_requeridas);

    return NULL;
}

/*
 * ----------------------------------------------------------------------------
 * Programa Principal (Main)
 * Inicializa recursos, crea hilos de usuarios y presenta estadísticas finales.
 * ----------------------------------------------------------------------------
 */
int main(int argc, char *argv[]) {
    int num_usuarios = NUM_USUARIOS_DEFAULT;

    if (argc > 1) {
        int n = atoi(argv[1]);
        if (n > 0) num_usuarios = n;
    }

    srand(time(NULL) ^ getpid());

    // Limpiar o inicializar el archivo de base de datos para esta corrida
    FILE *f_init = fopen(ARCHIVO_BD, "w");
    if (f_init) {
        char fecha_hora[64];
        time_t t_now = time(NULL);
        struct tm *tm_info = localtime(&t_now);
        strftime(fecha_hora, sizeof(fecha_hora), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(f_init, "=== BASE DE DATOS COMPARTIDA - CENTRO DE CÓMPUTOS ===\n");
        fprintf(f_init, "Sesión iniciada el: %s\n", fecha_hora);
        fprintf(f_init, "Licencias totales del sistema: %d\n", TOTAL_LICENCIAS);
        fprintf(f_init, "--------------------------------------------------------\n");
        fclose(f_init);
    }

    printf("\n===================================================================\n");
    printf("   UNS - SISTEMAS OPERATIVOS | LABORATORIO DE SINCRONIZACIÓN        \n");
    printf("   Control de Licencias Especializadas en Centro de Cómputos       \n");
    printf("===================================================================\n");
    printf(" * Licencias totales en el sistema:  %d\n", TOTAL_LICENCIAS);
    printf(" * Rango de demanda por usuario:     %d a %d licencias\n", MIN_LICENCIAS_REQ, MAX_LICENCIAS_REQ);
    printf(" * Cantidad de hilos de usuarios:    %d\n", num_usuarios);
    printf(" * Archivo de Base de Datos:         %s\n", ARCHIVO_BD);
    printf("===================================================================\n\n");

    pthread_t *hilos = (pthread_t*) malloc(num_usuarios * sizeof(pthread_t));
    if (!hilos) {
        perror("Error asignando memoria para los hilos");
        exit(EXIT_FAILURE);
    }

    // Creación de los hilos de usuarios con pequeños intervalos aleatorios
    total_solicitudes = num_usuarios;
    for (int i = 0; i < num_usuarios; i++) {
        int *id = (int*) malloc(sizeof(int));
        *id = i + 1;

        if (pthread_create(&hilos[i], NULL, hilo_usuario, id) != 0) {
            perror("Error creando hilo de usuario");
            free(id);
            exit(EXIT_FAILURE);
        }

        // Espaciado aleatorio entre llegadas de usuarios (0 a 40 ms)
        usleep((rand() % 40) * 1000);
    }

    // Esperar a que todos los hilos de usuarios terminen su ciclo
    for (int i = 0; i < num_usuarios; i++) {
        pthread_join(hilos[i], NULL);
    }

    free(hilos);

    // Destrucción limpia de primitivas de sincronización
    pthread_mutex_destroy(&mutex_licencias);
    pthread_mutex_destroy(&mutex_bd);
    pthread_mutex_destroy(&mutex_pantalla);

    // Verificación final del invariante del sistema
    printf("\n===================================================================\n");
    printf("                     RESUMEN Y MÉTRICAS FINALES                    \n");
    printf("===================================================================\n");
    printf(" Total de usuarios que arribaron:              %d\n", total_solicitudes);
    printf(" Usuarios que consiguieron licencias (éxito):  %d\n", usuarios_atendidos_exitosos);
    printf(" Usuarios rechazados (se retiraron sin nada):  %d\n", usuarios_rechazados);
    printf(" Registros guardados en la Base de Datos:      %d\n", total_registros_bd);
    printf("-------------------------------------------------------------------\n");
    printf(" Licencias disponibles iniciales:              %d\n", TOTAL_LICENCIAS);
    printf(" Licencias disponibles finales:                %d\n", licencias_disponibles);

    if (licencias_disponibles == TOTAL_LICENCIAS) {
        printf(" \033[1;32m[INVARIANTE OK]\033[0m Todas las licencias fueron restituidas con éxito.\n");
    } else {
        printf(" \033[1;31m[ERROR]\033[0m Fuga de licencias detectada (%d != %d).\n",
               licencias_disponibles, TOTAL_LICENCIAS);
    }
    printf("===================================================================\n\n");

    return 0;
}

# ==============================================================================
# Makefile - UNS Sistemas Operativos
# Laboratorio de Sincronización: Control de Licencias Especializadas
# ==============================================================================

CC = gcc
CFLAGS = -Wall -Wextra -pthread -O2 -std=gnu11
TARGET = centro_computos
SRC = centro_computos.c
BD_FILE = resultados_bd.txt

.PHONY: all run run-heavy clean help

all: $(TARGET)

$(TARGET): $(SRC)
	$(CC) $(CFLAGS) -o $(TARGET) $(SRC)
	@echo "Compilación exitosa: ./$(TARGET)"

run: $(TARGET)
	@echo "Ejecutando simulación estándar (30 usuarios)..."
	./$(TARGET) 30

run-heavy: $(TARGET)
	@echo "Ejecutando simulación de alta concurrencia (60 usuarios para saturar licencias)..."
	./$(TARGET) 60

clean:
	rm -f $(TARGET) $(BD_FILE)
	@echo "Limpieza completada."

help:
	@echo "Opciones disponibles:"
	@echo "  make            - Compila el programa ejecutable"
	@echo "  make run        - Compila y ejecuta con 30 usuarios"
	@echo "  make run-heavy  - Compila y ejecuta con 60 usuarios (alta carga)"
	@echo "  make clean      - Elimina binarios y archivos temporales de BD"
